import type { ProgramEntry } from '../../types/mol';
import { resolveProgramNoteKeys } from '../footnotes';

type RawBRow = [
  number,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string,
  string
];

function buildRows(rows: RawBRow[]): ProgramEntry[] {
  return rows.map(
    (
      [
        rowNumber,
        mosid,
        occupation,
        command,
        program,
        institution,
        meetsMajority,
        length,
        province,
        appendix,
        noteRef,
        accreditationType,
        location,
        publicPrivate,
      ],
      idx
    ) => ({
      id: `B-${rowNumber}-${idx}`,
      tableId: 'B',
      rowNumber,
      mosid,
      occupation,
      command,
      program,
      institution,
      meetsMajority,
      length,
      province,
      appendix,
      noteRef,
      accreditationType: accreditationType || undefined,
      location: location || undefined,
      publicPrivate: publicPrivate || undefined,
      resolvedNoteKeys: resolveProgramNoteKeys('B', appendix, noteRef),
    })
  );
}

